import{c as n,Z as s,Q as i,j as a,m as g,o as e,g as o,n as r}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"天问","description":"","frontmatter":{"title":"天问","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/4.md","filePath":"books/shici/chuci/4.md"}'),u={name:"books/shici/chuci/4.md"};function h(p,t,d,q,c,m){const l=s("PoemNav");return i(),a("div",null,[t[0]||(t[0]=g('<h1 id="天问" tabindex="-1">天问 <a class="header-anchor" href="#天问" aria-label="Permalink to &quot;天问&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>曰：遂古之初，谁传道之？ 上下未形，何由考之？ 冥昭瞢暗，谁能极之？ 冯翼惟象，何以识之？ 明明暗暗，惟时何为？ 阴阳三合，何本何化？</p><p>圜则九重，孰营度之？ 惟兹何功，孰初作之？ 斡维焉系，天极焉加？ 八柱何当，东南何亏？ 九天之际，安放安属？ 隅隈多有，谁知其数？</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li><strong>天问</strong>：对天发问，即向苍天提出疑问。这是屈原创作的一首奇特的长诗，全诗共提出一百七十多个问题。</li><li><strong>曰</strong>：发语词，一说指屈原自称，或指提问的开始。</li><li><strong>遂古</strong>：远古。遂，通&quot;邃&quot;，深远。</li><li><strong>初</strong>：开端。</li><li><strong>传道</strong>：传说，流传。</li><li><strong>上下</strong>：指天地。</li><li><strong>未形</strong>：尚未形成形体。</li><li><strong>何由</strong>：根据什么。</li><li><strong>考</strong>：考察，推究。</li><li><strong>冥昭瞢暗</strong>：昼夜未分，混沌不明的样子。冥，幽暗。昭，明亮。瞢暗，混沌不清。</li><li><strong>极</strong>：穷究，探求到底。</li><li><strong>冯翼</strong>：大气充盛弥漫的样子。冯，通&quot;凭&quot;，满。翼，盛。</li><li><strong>惟象</strong>：只有景象，无形无象。</li><li><strong>识</strong>：辨识，认识。</li><li><strong>明明暗暗</strong>：昼夜交替，明暗变化。</li><li><strong>惟时何为</strong>：这是为了什么。时，通&quot;是&quot;，此。</li><li><strong>阴阳</strong>：中国古代哲学概念，指宇宙间两种对立统一的基本力量。</li><li><strong>三合</strong>：三，指天、地、人；合，配合。一说指阴阳与气三者结合。</li><li><strong>何本何化</strong>：什么是本源，什么是变化。本，根本。化，化生。</li><li><strong>圜</strong>：同&quot;圆&quot;，指天。古人认为天圆地方。</li><li><strong>九重</strong>：九层。古人传说天有九层。</li><li><strong>孰</strong>：谁。</li><li><strong>营度</strong>：经营度量，规划测量。</li><li><strong>惟兹何功</strong>：这是何等功业。兹，此，指九重天。</li><li><strong>初作</strong>：最初建造。</li><li><strong>斡</strong>：旋转的枢纽，指天体旋转的轴心。</li><li><strong>维</strong>：维系，指系天的大绳。古人认为天由大绳维系。</li><li><strong>焉系</strong>：系在哪里。</li><li><strong>天极</strong>：天的顶端，北极星所在。</li><li><strong>焉加</strong>：架在哪里。加，放置，架设。</li><li><strong>八柱</strong>：支撑天的八根柱子。古代神话传说有八座山作为擎天柱。</li><li><strong>何当</strong>：在何处承当。当，承当，支撑。</li><li><strong>东南何亏</strong>：东南方为什么缺损。古代传说共工怒触不周山，天倾西北，地不满东南。</li><li><strong>九天</strong>：古人将天分为九层，中央钧天，东方苍天，东北变天，北方玄天，西北幽天，西方颢天，西南朱天，南方炎天，东南阳天。</li><li><strong>际</strong>：边界。</li><li><strong>安放</strong>：安置在何处。</li><li><strong>安属</strong>：连接在何处。属，连接。</li><li><strong>隅隈</strong>：角落和弯曲的地方。隅，角落。隈，弯曲处。</li><li><strong>谁知其数</strong>：谁能知道它们的数目。</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>请问：远古的开端，是谁将它传述下来？ 天地尚未形成，根据什么来考察推究？ 昼夜混沌不分，谁能穷究它的道理？ 大气弥漫只有景象，凭什么来辨识认识？ 明暗交替变化，这一切是为了什么？ 阴阳与天地人三者配合，什么是本源什么是化生？</p><p>天是圆的且有九重，是谁经营度量它？ 这是何等伟大的功业，是谁最初建造的？ 旋转的轴心和维系的大绳系在何处？ 天的顶端架设在何处？ 八根天柱支撑在何处？ 东南方为什么缺损？ 九天的边界，安置在哪里？连接在何处？ 角落和弯曲之处如此众多，谁能知道它们的数目？</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《天问》是屈原创作的一首极其独特的长诗，全诗三百七十余句，提出了一百七十多个问题，从天地开辟、宇宙生成，到神话传说、历史兴衰，无所不问，气势磅礴，构思奇特，是中国文学史上一部空前绝后的作品。</p><p>诗以&quot;曰&quot;字开篇，连续发问，开篇即追问宇宙的起源：&quot;遂古之初，谁传道之？上下未形，何由考之？&quot;诗人对远古混沌初开、天地未形的状态提出质疑，对阴阳变化、三才配合的本源进行追问，表现出强烈的探索精神和理性思辨色彩。</p><p>第二段转向对天体结构的追问：&quot;圜则九重，孰营度之？&quot;&quot;斡维焉系，天极焉加？&quot;诗人对天有九重、八柱擎天、天倾东南等神话传说提出一连串疑问，表现出不盲从传统、勇于质疑的科学精神。这些问题涉及天文学、宇宙论，在先秦时期具有极高的思想价值。</p><p>《天问》的独特之处在于：它通篇只有问句，没有答语；它不问人事而先问天地，体现了屈原宏大的宇宙意识；它质疑神话传说，表现出理性批判精神。全诗气势磅礴，句式整齐，四言为主，节奏鲜明，具有独特的艺术魅力。</p><p>此诗不仅是中国文学史上的奇篇，也是思想史上的杰作。它反映了屈原对自然、历史、人生的深刻思考，体现了他追求真理、探索未知的精神品格。后世李白、柳宗元等诗人皆受其影响，柳宗元更作《天对》以答屈原之问，成为中国思想史上的一段佳话。</p>',16)),e(l),t[1]||(t[1]=o("hr",null,null,-1)),t[2]||(t[2]=o("h2",{id:"关于作者",tabindex:"-1"},[r("关于作者 "),o("a",{class:"header-anchor",href:"#关于作者","aria-label":'Permalink to "关于作者"'},"​")],-1)),t[3]||(t[3]=o("blockquote",null,[o("p",null,[o("strong",null,"屈原"),r("（约公元前340年－公元前278年），名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，被誉为“中华诗祖”。")]),o("p",null,[o("a",{href:"/authors/quyuan.html"},"查看作者详情 →")])],-1))])}const f=n(u,[["render",h]]);export{b as __pageData,f as default};
